export const entities = ERON.entities;
export const byId = Object.fromEntries(ERON.entities.map(e => [e.id, e]));
export const byTitle = Object.fromEntries(ERON.entities.map(e => [e.title, e]));
export const byClass = ERON.entities.reduce((m, e) => ((m[e.class] ||= []).push(e), m), {});
export const exists = title => Object.prototype.hasOwnProperty.call(byTitle, title);
/** Every redlink in the curated subset, deduplicated, most-wanted first. */
export const redlinks = [...new Set(ERON.entities.flatMap(e => e.redlinks))];
export default ERON;

if (typeof window !== 'undefined') {
  window.ERON = ERON;
  window.ERON.byId = byId; window.ERON.byTitle = byTitle; window.ERON.byClass = byClass;
}
